 private void auth(){ImageView mark=new ImageView(this);mark.setImageResource(R.drawable.ic_logo);LinearLayout.LayoutParams hero=new LinearLayout.LayoutParams(dp(88),dp(88));hero.gravity=Gravity.CENTER_HORIZONTAL;hero.setMargins(0,dp(12),0,dp(22));mark.setContentDescription("Geo Attend");content.addView(mark,hero);title(initialized?"Welcome back.":"Set up your team.");paragraph(content,initialized?"Your private office workspace. Sign in with your assigned ID and PIN.":"The first account is the administrator. Create your login and set your workplace.");LinearLayout c=card(content);final EditText name=initialized?null:field(c,"Admin name","Your full name",false);EditText login=field(c,"Login ID","Enter your login ID",false);login.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD);EditText pin=field(c,"PIN","6–12 digits",true);final PlaceForm place=initialized?null:new PlaceForm(c,null);button(c,initialized?"Log in to workspace":"Create admin & workplace",true,()->{String l=value(login),p=value(pin);if(!l.matches("[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}")||!p.matches("[0-9]{6,12}")){notice("Enter a valid login ID and a 6–12 digit PIN.");return;}if(!initialized){try{JSONObject b=place.body();b.put("name",value(name));b.put("login",l.toLowerCase(Locale.ROOT));b.put("pin",p);task(()->Api.call(this,"setup",b),r->{initialized=true;screen();feedback("Admin created. Log in using your new ID and PIN.");showRecoveryCode(((JSONObject)r).optString("recoveryCode"));});}catch(Exception e){notice(e.getMessage());}}else task(()->{JSONObject j=Api.call(this,"login",Api.body("login",l.toLowerCase(Locale.ROOT),"pin",p));store.setToken(j.getString("token"));return Api.call(this,"status",null);},r->{JSONObject j=(JSONObject)r;user=j.optJSONObject("user");office=j.optJSONObject("office");store.savePrivate("cachedStatus",j.toString());offline=false;store.prefs().edit().putString("user",user==null?"":user.toString()).apply();view="Overview";screen();if(user!=null){PushMessaging.refresh(this);main.postDelayed(this::adminNotificationPermission,500);loadStats(true);if(isEmployee()){main.postDelayed(this::askTracking,350);main.postDelayed(()->TrackingDiagnostics.reportInactive(this),3000);}}});});paragraph(content,"Your PIN is never saved on this phone. The session is encrypted using Android Keystore.");if(initialized)button(content,"Recover admin access",false,this::recoverAdmin);button(content,"Retry service connection",false,this::loadStatus);TextView version=text("Geo Attend · Version 3.3.1",11,MUTED,false);version.setGravity(Gravity.CENTER);version.setPadding(0,dp(24),0,0);content.addView(version);}
 private class PlaceForm {EditText name,lat,lon;Spinner radius;PlaceForm(LinearLayout c,JSONObject o){name=field(c,"Workplace name","Main office",false);lat=field(c,"Latitude","12.97160",false);lon=field(c,"Longitude","77.59460",false);lat.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);lon.setInputType(lat.getInputType());TextView l=text("Attendance radius",11,INK,true);l.setPadding(0,dp(18),0,dp(7));c.addView(l);radius=new Spinner(MainActivity.this);radius.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_spinner_dropdown_item,new String[]{"50 metres","55 metres","60 metres","65 metres","70 metres","75 metres","80 metres"}){public View getView(int pos,View old,ViewGroup parent){TextView v=(TextView)super.getView(pos,old,parent);v.setTextColor(INK);v.setBackgroundColor(Color.TRANSPARENT);return v;}public View getDropDownView(int pos,View old,ViewGroup parent){TextView v=(TextView)super.getDropDownView(pos,old,parent);v.setTextColor(INK);v.setBackgroundColor(BG);v.setMinHeight(dp(48));return v;}});radius.setSelection(3);c.addView(radius,new LinearLayout.LayoutParams(-1,dp(48)));if(o!=null){name.setText(o.optString("name"));lat.setText(String.valueOf(o.optDouble("lat")));lon.setText(String.valueOf(o.optDouble("lon")));radius.setSelection(Math.max(0,Math.min(6,(o.optInt("radius",65)-50)/5)));}button(c,"Use my current location",false,()->useCurrent(this));}
 JSONObject body() throws Exception {double a,b;try{a=Double.parseDouble(value(lat));b=Double.parseDouble(value(lon));}catch(Exception e){throw new Exception("Enter valid workplace coordinates.");}if(value(name).isEmpty()||a< -90||a>90||b< -180||b>180||Double.isNaN(a)||Double.isNaN(b))throw new Exception("Enter a workplace name and valid coordinates.");return Api.body("office",value(name),"lat",a,"lon",b,"radius",50+radius.getSelectedItemPosition()*5);}}
 private PlaceForm pendingPlace=null;private void useCurrent(PlaceForm p){pendingPlace=p;if(!fine()){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},102);return;}feedback("Finding workplace coordinates…");LocationManager m=(LocationManager)getSystemService(LOCATION_SERVICE);String provider=m.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER;try{if(Build.VERSION.SDK_INT>=30){m.getCurrentLocation(provider,null,getMainExecutor(),l->{if(l==null){notice("Could not get GPS. Enter the coordinates or try outdoors.");return;}p.lat.setText(String.valueOf(l.getLatitude()));p.lon.setText(String.valueOf(l.getLongitude()));feedback("Location added. Save to set this workplace.");});}else{final LocationListener listener=new LocationListener(){public void onLocationChanged(Location l){m.removeUpdates(this);p.lat.setText(String.valueOf(l.getLatitude()));p.lon.setText(String.valueOf(l.getLongitude()));feedback("Location added. Save to confirm.");}public void onStatusChanged(String s,int n,Bundle b){}public void onProviderEnabled(String s){}public void onProviderDisabled(String s){}};m.requestSingleUpdate(provider,listener,Looper.getMainLooper());main.postDelayed(()->m.removeUpdates(listener),20000);}}catch(Exception e){notice("Turn on device location and try again.");}}
 private void loadStats(boolean redraw){if(user==null||busy||navigating||sheetOpen||formMode&&!redraw)return;final String requestedView=view;task(()->{try{JSONObject j=Api.call(this,"stats",null);store.savePrivate("cachedStats",j.toString());store.prefs().edit().putLong("cachedAt",System.currentTimeMillis()).apply();offline=false;return j;}catch(java.io.IOException e){if(e instanceof Api.Failure&&((Api.Failure)e).code<500)throw e;String cached=store.readPrivate("cachedStats");if(cached.isEmpty())throw e;offline=true;return new JSONObject(cached);}},r->{JSONObject j=(JSONObject)r;employees=j.optJSONArray("employees");records=j.optJSONArray("records");office=j.optJSONObject("office");if(employees==null)employees=new JSONArray();if(records==null)records=new JSONArray();synced=offline?store.prefs().getLong("cachedAt",0):System.currentTimeMillis();syncedElapsed=android.os.SystemClock.elapsedRealtime();if(isAdmin()&&getIntent().hasExtra("attendanceEmployee")){openPushAttendance();getIntent().removeExtra("attendanceEmployee");screen();return;}if("Attendance".equals(view)&&!redraw&&attendanceList!=null){refreshAttendanceList();updateSyncBanner();}else if(!sheetOpen&&!formMode&&!navigating&&requestedView.equals(view)&&(redraw||"Overview".equals(view)||"Employees".equals(view)||"Attendance".equals(view)))screen(true);});}
 private JSONObject employee(String id){for(int i=0;i<employees.length();i++){JSONObject e=employees.optJSONObject(i);if(e!=null&&id.equals(e.optString("id")))return e;}return null;}
 private long serverNow(){return System.currentTimeMillis()+store.prefs().getLong("serverOffset",0);}
 private String phoneHealth(JSONObject e){return TrackingHealth.label(e.optString("tracking_health"),e.optLong("last_contact"),e.optLong("last_seen"),serverNow(),offline);}
 private long lastSeen(String id){JSONObject e=employee(id);return e==null?0:e.optLong("last_seen");}private boolean working(String id){if(offline||android.os.SystemClock.elapsedRealtime()-syncedElapsed>45000||serverNow()-lastSeen(id)>90000)return false;for(int i=0;i<records.length();i++){JSONObject r=records.optJSONObject(i);if(r!=null&&id.equals(r.optString("account"))&&r.isNull("end"))return true;}return false;}
 private long todayMillis(String id){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);long start=c.getTimeInMillis(),total=0;for(int i=0;i<records.length();i++){JSONObject r=records.optJSONObject(i);if(r==null||!id.isEmpty()&&!id.equals(r.optString("account")))continue;long end=r.isNull("end")?lastSeen(r.optString("account")):r.optLong("end");total+=Math.max(0,end-Math.max(start,r.optLong("start")));}return total;}
 private String duration(long ms){long m=Math.max(0,ms)/60000;return m/60+"h "+String.format(Locale.ROOT,"%02d",m%60)+"m";}private String stamp(long n){return n==0?"—":new SimpleDateFormat("dd MMM, h:mm a",Locale.getDefault()).format(new Date(n));}
 private void overview(){title("Hello, "+user.optString("name").split(" ")[0]+".");paragraph(content,isAdmin()?"Your team’s working day, in one place.":"Your attendance starts when you arrive.");int count=0,active=0;for(int i=0;i<employees.length();i++){JSONObject e=employees.optJSONObject(i);if(e!=null&&e.optInt("active")==1){active++;if(working(e.optString("id")))count++;}}LinearLayout stats=card(content);stats.addView(text(isAdmin()?"CHECKED IN NOW":"ATTENDANCE STATUS",10,MUTED,true));if(isAdmin()){TextView countText=text(offline?"Saved dashboard":count+" / "+active,30,offline?amber():GREEN,true);stats.addView(countText);}else{statusBadge=text("",18,INK,true);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.setMargins(0,dp(12),0,dp(8));stats.addView(statusBadge,bp);String label=attendanceLabel();badge(statusBadge,label,attendanceColor(label));}detail(stats,isAdmin()?"Team hours today":"Hours today",duration(todayMillis(isAdmin()?"":user.optString("id"))),INK);if(isEmployee()){long check=latestCheckIn();detail(stats,"Latest check-in",check==0?"—":new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date(check)),INK);if(new OfflineAttendance(this).pendingCount()>0)detail(stats,"Offline hours pending",duration(new OfflineAttendance(this).todayMillis()),amber());}if(isAdmin()){button(stats,"Add an employee",true,this::addEmployee);}else{LinearLayout tracking=card(content);tracking.addView(text("LIVE LOCATION ATTENDANCE",10,GREEN,true));live=text("",20,INK,true);live.setPadding(0,dp(14),0,dp(12));tracking.addView(live);liveDistance=detail(tracking,"Workplace distance","—",INK);liveAccuracy=detail(tracking,"GPS accuracy","—",INK);liveUpdated=detail(tracking,"Last location update","—",INK);livePending=detail(tracking,"Records awaiting sync","0",INK);syncIssueText=text("",13,amber(),false);tracking.addView(syncIssueText);paragraph(tracking,"Manage location tracking in Settings.");updateLive();}if(office!=null){LinearLayout c=card(content);c.addView(text("YOUR WORKPLACE",10,MUTED,true));paragraph(c,office.optString("name"));c.addView(text(office.optInt("radius")+" m attendance zone",25,GREEN,true));paragraph(c,String.format(Locale.US,"%.5f, %.5f",office.optDouble("lat"),office.optDouble("lon")));}if(isAdmin()&&active==0){LinearLayout c=card(content);c.addView(text("Your workplace is ready.",18,INK,true));paragraph(c,"Add your team and assign each employee their own login ID and PIN.");button(c,"Add first employee",true,this::addEmployee);}LinearLayout c=card(content);c.addView(text("Recent attendance",18,INK,true));showRecords(c,4,"");button(c,"View all attendance",false,()->navigate("Attendance"));}
 private void updateLive(){if(syncIssueText!=null){String issue=store.prefs().getString("syncIssue","");syncIssueText.setText(issue);syncIssueText.setVisibility(issue.isEmpty()?View.GONE:View.VISIBLE);}boolean running=AttendanceService.running;if(trackingButton!=null)trackingButton.setText(running?"Pause location tracking":"Enable automatic attendance");updateSyncBanner();if(statusBadge!=null){String label=attendanceLabel();badge(statusBadge,label,attendanceColor(label));}if(live==null)return;long at=store.prefs().getLong("statusAt",0),fixAt=store.prefs().getLong("fixAt",0),age=System.currentTimeMillis()-at;String status=!running?"Location tracking paused":age>45000?"Waiting for fresh GPS":store.prefs().getString("trackingStatus","Finding your location");live.setText(status);live.setTextColor(attendanceColor(attendanceLabel()));int pending=new OfflineAttendance(this).pendingCount(),accuracy=store.prefs().getInt("accuracy",0);boolean fresh=running&&age<=45000&&accuracy>0;liveDistance.setText(fresh?store.prefs().getInt("distance",0)+" m":"—");liveAccuracy.setText(fresh?"±"+accuracy+" m":"—");liveAccuracy.setTextColor(fresh&&office!=null&&accuracy>office.optInt("radius")?amber():INK);liveUpdated.setText(fixAt==0?"—":new SimpleDateFormat("h:mm:ss a",Locale.getDefault()).format(new Date(fixAt)));livePending.setText(String.valueOf(pending));livePending.setTextColor(pending>0?amber():INK);}

 private void askTracking(){if(!isEmployee())return;new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Enable automatic attendance?").setMessage("Geo Attend will use precise GPS while you work, including when the screen is off, to check you in and out of your workplace. A persistent notification shows that tracking is active. While offline, attendance is saved securely on this phone and synced after reconnection. No route history is recorded. You can pause at any time.").setPositiveButton("Enable tracking",(d,w)->{if(!fine()){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},101);}else notificationPermission();}).setNegativeButton("Not now",null).show();}
 private void notificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},103);else startServiceVisible();}
 private void startServiceVisible(){if(!resumed||!fine()||!isEmployee())return;try{startForegroundService(new Intent(this,AttendanceService.class));main.postDelayed(this::updateLive,1000);}catch(Exception e){notice("Could not start tracking. Check precise location permission.");}}
