 private void managePhones(String account,String name){if(!isAdmin()||busy)return;task(()->Api.call(this,"devices&employee="+java.net.URLEncoder.encode(account,"UTF-8"),null),r->{JSONArray devices=((JSONObject)r).getJSONArray("devices");if(devices.length()==0){new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("No phone requests").setMessage("Ask "+name+" to log in using version 3.1. Their phone will appear here for approval.").setPositiveButton("Close",null).show();return;}String[] names=new String[devices.length()];for(int i=0;i<devices.length();i++){JSONObject phone=devices.getJSONObject(i);names[i]=phone.getString("name")+" · "+phone.getString("id").substring(0,8)+"\n"+phone.getString("state");}new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Authorised phone · "+name).setItems(names,(d,pos)->{JSONObject phone=devices.optJSONObject(pos);if("approved".equals(phone.optString("state"))){feedback("This phone is already authorised.");return;}new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Approve this phone?").setMessage(names[pos]+"\n\nThe previous phone is revoked and attendance ends at its latest confirmed update. Ask the employee to sync pending attendance before changing phones.").setPositiveButton("Approve",(dialog,w)->task(()->Api.call(this,"approveDevice",Api.body("account",account,"device",phone.getString("id"))),result->{feedback("Phone approved. The employee can log in again.");loadStats(true);})).setNegativeButton("Cancel",null).show();}).setNegativeButton("Close",null).show();});}
 private void addEmployee(){if(!isAdmin()||busy)return;shell();formMode=true;title("Add an employee");LinearLayout c=card(content);EditText name=field(c,"Employee name","Full name",false),login=field(c,"Login ID","employee.01",false),pin=field(c,"PIN","6–12 digits",true);button(c,"Create employee",true,()->{if(value(name).isEmpty()||!value(login).matches("[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}")||!value(pin).matches("[0-9]{6,12}")){notice("Enter a name, a valid login ID, and a 6–12 digit PIN.");return;}final String employeeName=value(name),employeeLogin=value(login).toLowerCase(Locale.ROOT),employeePin=value(pin);task(()->Api.call(this,"employees",Api.body("name",employeeName,"login",employeeLogin,"pin",employeePin)),r->{view="Employees";screen();loadStats(true);Toast.makeText(this,"Employee created. Share their ID and PIN directly.",Toast.LENGTH_LONG).show();});});button(c,"Cancel",false,this::screen);paragraph(content,"Give the employee their credentials directly. PINs cannot be viewed after creation.");}
 private void attendanceScreen(){title("Attendance history");paragraph(content,"Automatic arrivals, departures, and working hours.");if(isAdmin()){Spinner filter=new Spinner(this);List<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("All employees");ids.add("");for(int i=0;i<employees.length();i++){JSONObject e=employees.optJSONObject(i);if(e!=null){names.add(e.optString("name")+(e.optInt("active")==0?" (removed)":""));ids.add(e.optString("id"));}}filter.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));int selected=Math.max(0,ids.indexOf(employeeFilter));employeeFilter=ids.get(selected);filter.setSelection(selected);content.addView(filter);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);attendanceList=list;content.addView(list);showRecords(list,100,employeeFilter);filter.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int pos,long id){String selectedId=ids.get(pos);if(selectedId.equals(employeeFilter))return;employeeFilter=selectedId;list.removeAllViews();showRecords(list,100,employeeFilter);}public void onNothingSelected(AdapterView<?> a){}});}else{attendanceList=new LinearLayout(this);attendanceList.setOrientation(LinearLayout.VERTICAL);content.addView(attendanceList);showRecords(attendanceList,100,"");}button(content,"Export attendance CSV",true,()->export(employeeFilter));paragraph(content,"Times are shown in your phone’s timezone. CSV timestamps use UTC. Interrupted tracking ends time at the last verified GPS update.");button(content,"Refresh attendance",false,()->loadStats(true));}
 private void refreshAttendanceList(){final ScrollView target=dashboardScroll;final int position=target.getScrollY();attendanceList.removeAllViews();showRecords(attendanceList,100,isAdmin()?employeeFilter:"");target.getViewTreeObserver().addOnPreDrawListener(new android.view.ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){if(target.getViewTreeObserver().isAlive())target.getViewTreeObserver().removeOnPreDrawListener(this);if(dashboardScroll==target)target.scrollTo(0,position);return true;}});}
 private void showRecords(LinearLayout parent,int limit,String id){List<JSONObject> items=new ArrayList<>();if(isEmployee()){JSONArray pending=new OfflineAttendance(this).pendingRecords();for(int k=0;k<pending.length();k++){JSONObject r=pending.optJSONObject(k);if(r!=null)try{JSONObject item=new JSONObject(r.toString());item.put("pending",true);items.add(item);}catch(JSONException ignored){}}}for(int i=0;i<records.length();i++){JSONObject r=records.optJSONObject(i);if(r!=null&&(id.isEmpty()||id.equals(r.optString("account"))))items.add(r);}items.sort((a,b)->Long.compare(b.optLong("start"),a.optLong("start")));String lastDay="";int shown=0;for(JSONObject r:items){if(shown++>=limit)break;String day=new SimpleDateFormat("EEEE, d MMM yyyy",Locale.getDefault()).format(new Date(r.optLong("start")));if(!day.equals(lastDay)){TextView date=text(day,13,INK,true);date.setPadding(0,dp(22),0,dp(2));parent.addView(date);lastDay=day;}LinearLayout c=card(parent);boolean pending=r.optBoolean("pending"),open=r.isNull("end"),active=!pending&&open&&working(r.optString("account"));if(isAdmin())c.addView(text(r.optString("name"),17,INK,true));String label=pending?"Pending sync":open?(active?"Checked in":isAdmin()&&employee(r.optString("account"))!=null?phoneHealth(employee(r.optString("account"))):"Waiting for verified location"):r.optString("reason").equals("offline device record")?"Synced offline attendance":r.optString("reason").equals("tracking interrupted")?"Ended · no verified location update":"Completed";TextView status=text("",12,INK,true);badge(status,label,pending||open&&!active?amber():active?GREEN:MUTED);c.addView(status,new LinearLayout.LayoutParams(-2,-2));SimpleDateFormat clock=new SimpleDateFormat("h:mm a",Locale.getDefault());detail(c,"Arrival",clock.format(new Date(r.optLong("start"))),INK);detail(c,pending?"Last confirmed": "Departure",open?"—":clock.format(new Date(r.optLong("end"))),INK);long end=open?lastSeen(r.optString("account")):r.optLong("end");detail(c,"Total hours",duration(end-r.optLong("start")),GREEN);if(!pending&&!open&&!r.optString("reason").isEmpty())paragraph(c,r.optString("reason"));}if(items.isEmpty())paragraph(parent,"No attendance records yet. They appear automatically when an employee enters the workplace.");}

