 private LinearLayout sheet(String heading){if(activeSheet!=null&&activeSheet.isShowing())activeSheet.dismiss();Dialog dialog=new Dialog(this);activeSheet=dialog;sheetOpen=true;LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(12),dp(10),dp(12),dp(24));GradientDrawable bg=glass(26);bg.setColor(dark?Color.rgb(20,31,25):Color.rgb(248,252,245));panel.setBackground(bg);View handle=new View(this);handle.setBackground(shape(MUTED,3));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(46),dp(4));hp.gravity=Gravity.CENTER_HORIZONTAL;hp.bottomMargin=dp(15);panel.addView(handle,hp);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView name=text(heading,23,INK,true);name.setPadding(dp(12),0,0,0);top.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button close=new Button(this);close.setText("×");close.setTextSize(26);close.setTextColor(INK);close.setContentDescription("Close "+heading);close.setBackground(ripple(shape(Color.TRANSPARENT,24),24));top.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));close.setOnClickListener(v->dialog.dismiss());panel.addView(top);ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(12),dp(8),dp(12),dp(8));scroll.addView(body);panel.addView(scroll,new LinearLayout.LayoutParams(-1,-2));dialog.setContentView(panel);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attrs=w.getAttributes();attrs.dimAmount=.6f;attrs.gravity=Gravity.BOTTOM;w.setAttributes(attrs);}dialog.setOnDismissListener(d->{if(activeSheet==dialog){activeSheet=null;sheetOpen=false;trackingButton=null;}});dialog.show();if(w!=null){w.setLayout(-1,-2);w.setGravity(Gravity.BOTTOM);}panel.post(()->{int max=(int)(getResources().getDisplayMetrics().heightPixels*.84f);if(panel.getHeight()>max){LinearLayout.LayoutParams sp=(LinearLayout.LayoutParams)scroll.getLayoutParams();sp.height=Math.max(dp(180),max-dp(105));scroll.setLayoutParams(sp);}if(motion()){panel.setTranslationY(dp(60));panel.setAlpha(0);panel.animate().translationY(0).alpha(1).setDuration(250).setInterpolator(new DecelerateInterpolator()).start();}});return body;}
 private void profileSheet(){LinearLayout b=sheet(isAdmin()?"Admin Profile":"Employee Profile");b.addView(text(user.optString("name"),24,GREEN,true));paragraph(b,"Login ID · "+user.optString("login")+"\nRole · "+(isAdmin()?"Administrator":"Employee"));if(office!=null)paragraph(b,"Workplace · "+office.optString("name"));paragraph(b,"Profile photo is optional and stored encrypted on this phone for this account. It does not sync to other phones.");button(b,"Choose profile photo",true,()->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("image/*");try{startActivityForResult(pick,302);}catch(ActivityNotFoundException e){feedback("No photo picker is available on this phone.");}});if(AvatarStore.has(this,user.optString("id")))button(b,"Remove profile photo",false,()->{AvatarStore.remove(this,user.optString("id"));if(activeSheet!=null)activeSheet.dismiss();screen(true);feedback("Profile photo removed.");});}
