 private void appearanceSheet(){LinearLayout b=sheet("Appearance");paragraph(b,"Choose the appearance for this phone. AMOLED is the default; its ambient colours change each time you close and reopen the app.");String[] modes={"amoled","dark","light","emerald","slate"},labels={"AMOLED · Default","Dark","Light","Emerald Glass","Frosted Slate"},details={"Pure black with random ambient light","Soft charcoal surfaces","Bright, clear surfaces","Deep green with a luminous emerald glow","Cool slate with softly frosted surfaces"};for(int i=0;i<modes.length;i++){final String mode=modes[i];Button choice=button(b,(themeMode.equals(mode)?"✓  ":"")+labels[i],themeMode.equals(mode),()->setAppearance(mode));choice.setContentDescription(labels[i]+". "+details[i]+(themeMode.equals(mode)?". Selected":""));paragraph(b,details[i]);}Switch reduce=new Switch(this);reduce.setText("Reduce motion");reduce.setTextColor(INK);reduce.setTextSize(15);reduce.setMinHeight(dp(48));reduce.setChecked(store.prefs().getBoolean("reduceMotion",false));b.addView(reduce);reduce.setOnCheckedChangeListener((v,on)->store.prefs().edit().putBoolean("reduceMotion",on).apply());}
 private void setAppearance(String mode){if(busy||navigating||mode.equals(themeMode))return;Bitmap old=null;if(motion()&&root!=null&&root.getWidth()>0){try{old=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(old));}catch(OutOfMemoryError ignored){}}if(activeSheet!=null)activeSheet.dismiss();store.prefs().edit().putString("themeMode",mode).apply();screen(true);final Bitmap before=old;if(before!=null){ImageView overlay=new ImageView(this);overlay.setImageBitmap(before);overlay.setScaleType(ImageView.ScaleType.FIT_XY);addContentView(overlay,new ViewGroup.LayoutParams(-1,-1));overlay.animate().alpha(0).setDuration(260).withEndAction(()->{((ViewGroup)overlay.getParent()).removeView(overlay);overlay.setImageDrawable(null);before.recycle();}).start();}}
