 private void notificationsSheet(){if(!isAdmin())return;PushMessaging.refresh(this);LinearLayout b=sheet("Notifications");paragraph(b,"Silent employee check-in and check-out updates. Tap an alert to open that employee’s attendance. No sound or vibration by default.");boolean allowed=getSystemService(android.app.NotificationManager.class).areNotificationsEnabled();paragraph(b,allowed?"Phone notifications: allowed":"Phone notifications: blocked");paragraph(b,store.prefs().getString("pushRegistrationStatus","Connecting this admin phone…"));button(b,"Notification settings",false,()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));button(b,"Check server connection",false,()->task(()->Api.call(this,"pushStatus",null),r->{JSONObject j=(JSONObject)r;feedback(!j.optBoolean("configured")?"Complete the Windows notification setup first.":j.optBoolean("registered")?"This admin phone is connected.":"Phone registration pending. Close and reopen Notifications.");}));button(b,"Send silent test",true,()->{if(!getSystemService(android.app.NotificationManager.class).areNotificationsEnabled()){feedback("Allow notifications in Android settings first.");return;}task(()->{String token=com.google.android.gms.tasks.Tasks.await(com.google.firebase.messaging.FirebaseMessaging.getInstance().getToken(),15,java.util.concurrent.TimeUnit.SECONDS);Api.call(this,"registerPush",Api.body("token",token));return Api.call(this,"testPush",new JSONObject());},r->feedback(((JSONObject)r).optString("message","Test queued.")));});paragraph(b,"Internet and notification permission are required. Android may delay delivery during power saving; a force-stopped app must be opened again.");}
 private void controlsSheet(){if(!isEmployee())return;LinearLayout b=sheet("Controls");b.addView(text("Automatic attendance",20,INK,true));paragraph(b,"Enable or pause workplace attendance. Live location, distance, accuracy, and pending offline records remain on Overview.");trackingButton=button(b,AttendanceService.running?"Pause automatic attendance":"Enable automatic attendance",true,()->{if(AttendanceService.running)pause();else askTracking();});button(b,"Location & battery settings",false,this::locationBatterySettings);button(b,"Sync saved attendance",false,()->task(()->{new OfflineAttendance(this).connected();new OfflineAttendance(this).sync();store.prefs().edit().remove("syncIssue").apply();return new OfflineAttendance(this).pendingCount();},r->{feedback((Integer)r==0?"Saved attendance synced.":"More records remain. Tap again to sync the next batch.");loadStats(false);}));String issue=store.prefs().getString("syncIssue","");if(!issue.isEmpty())paragraph(b,issue);updateLive();}
 private void workplaceSheet(){if(!isAdmin())return;LinearLayout b=sheet("Workplace");paragraph(b,"Set your office name, coordinates, and a 50–80 metre attendance radius.");PlaceForm form=new PlaceForm(b,office);button(b,"Save workplace",true,()->{try{JSONObject body=form.body();new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Save this workplace?").setMessage("Changing the workplace ends active sessions at their latest verified GPS update. Employees reconnect using fresh GPS.").setPositiveButton("Save",(d,w)->task(()->Api.call(this,"settings",body),r->{if(activeSheet!=null)activeSheet.dismiss();loadStatus();feedback("Workplace updated.");})).setNegativeButton("Cancel",null).show();}catch(Exception e){feedback(e.getMessage());}});}
 private void securitySheet(){if(!isAdmin())return;LinearLayout b=sheet("Security & Backup");b.addView(text("Account recovery",19,INK,true));paragraph(b,user.optBoolean("recoveryReady")?"A recovery code is configured. Keep its saved copy private. Replacing it invalidates the old code.":"Create a recovery code before you forget your admin PIN. It is shown only when generated.");button(b,user.optBoolean("recoveryReady")?"Replace recovery code":"Create recovery code",false,()->{if(activeSheet!=null)activeSheet.dismiss();createRecovery();});b.addView(text("Manual encrypted backup",19,INK,true));paragraph(b,"On your Windows computer, run backup.cmd from the v3.1 server folder. Save the encrypted backup and keep its password separately. No paid backup subscription is required.");}
 private void aboutSheet(){LinearLayout b=sheet("About Geo Attend");b.addView(text("Geo Attend",26,GREEN,true));paragraph(b,"Version 3.3.1\nPrivate office attendance for Android.");b.addView(text("How attendance works",19,INK,true));paragraph(b,"• A reliable GPS fix inside the workplace checks you in.\n• Two reliable outside fixes, at least 15 seconds apart, check you out.\n• After 90 seconds without verified updates, recorded time ends at the last confirmed location.\n• Offline records wait for syncing; GPS, battery restrictions, or force-stop can interrupt tracking.");}

