 @Override public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==302){externalActivity=false;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&user!=null)importAvatar(data.getData());return;}if(req==201&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();String id=csvEmployee;task(()->{String csv=Api.raw(this,"export"+(id.isEmpty()?"":"&employee="+java.net.URLEncoder.encode(id,"UTF-8")),null);try(OutputStream stream=getContentResolver().openOutputStream(uri,"wt")){if(stream==null)throw new Exception("Could not save CSV.");stream.write(csv.getBytes(java.nio.charset.StandardCharsets.UTF_8));}return null;},r->feedback("CSV saved to your selected location."));}}
 private void logout(){if(busy)return;if(new OfflineAttendance(this).pendingCount()>0){notice("Reconnect and sync your offline attendance before logging out.");return;}new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Log out?").setMessage("Location tracking will stop. Your attendance history stays saved.").setPositiveButton("Log out",(d,w)->{store.prefs().edit().putBoolean("trackingWanted",false).apply();stopService(new Intent(this,AttendanceService.class));task(()->{try{Api.call(this,"logout",new JSONObject());return "";}catch(Exception e){return "Signed out on this phone. The server could not be reached.";}finally{store.clear();}},r->{user=null;records=new JSONArray();employees=new JSONArray();screen();if(!((String)r).isEmpty())notice((String)r);});}).setNegativeButton("Cancel",null).show();}
